hydraulic:{pressure:['Basınç düşük',['Yağ seviyesi','Emişte hava/kaçak','Filtre tıkalı','Relief valf','Pompa aşınması','İç kaçak'],['Seviye ve sıcaklığı kontrol et','Manometreyi doğrula','Emiş hattı kaçak/kısıt kontrolü','Filtre göstergesini kontrol et','Relief ayarını kontrol et','Pompa debisi ve iç kaçak testine ilerle']],heat:['Yağ ısınıyor',['Relief üzerinden sürekli dönüş','Filtre/hat daralması','Yanlış viskozite','Soğutucu yetersiz','Pompa verim kaybı'],['Tank sıcaklık trendini izle','Relief/bypass kontrolü','Filtre basınç kaybı','Yağ tipi-seviye kontrolü','Eşanjör/fan kontrolü']],leak:['Hidrolik kaçak',['Hortum/rakor','Keçe/O-ring','Silindir mili hasarı','Aşırı basınç','Valf blok conta'],['Basıncı güvenli tahliye et','Kaçak bölgesini temizleyip kaynağı bul','Hortum/rakor kontrolü','Mil-keçe yüzeyini incele','Sistem ve relief basıncını doğrula']],slow:['Hareket yavaş',['Debi düşük','Filtre tıkalı','Pompa aşınmış','Debi valfi kısık','Silindir iç kaçağı'],['Hareket sırasında basınç ve süre ölç','Pompa debisini kontrol et','Filtre/emiş hattı kısıtı','Debi valfi ayarı','Silindir iç kaçak testi']]},
pneumatic:{pressure:['Basınç düşük',['Kompresör/ana hat','Kaçak','FRL tıkalı','Regülatör ayarı','Hortum çapı'],['Ana hat ve makine girişini karşılaştır','FRL kontrolü','Kaçak testi','Hareket sırasında basınç düşümünü izle','Hortum/bağlantı/susturucu kontrolü']],leak:['Hava kaçağı',['Rakor','Hortum','Valf iç kaçağı','Silindir keçesi','FRL drenajı'],['Makine dururken kaçak sesi','Rakor/hortum bölgesel test','Valf egzozu kontrolü','Silindir iç kaçak','FRL/drenaj kontrolü']],slow:['Silindir yavaş',['Debi ayarı','Düşük basınç','Susturucu tıkalı','Silindir sürtünmesi','Valf debisi'],['Hareket sırasında basıncı ölç','Debi valflerini kontrol et','Susturucu kontrolü','Silindiri mekanik yükten ayırarak kıyasla','Valf/hortum kesiti']],water:['Hatta su / nem',['Tank drenajı','Kurutucu yetersiz','FRL dolu','Hat drenajı yanlış'],['Tank tahliyesi','Kurutucu kontrolü','FRL su tutucu','Hat düşük nokta drenajları']]},
